mapper.select:
SELECT file_size AS size, file_type AS extension
FROM sys_file
WHERE tenant_id = #{tenantId} AND file_id = #{fileId} AND deleted = 0
    AND biz_type = 'WORKFLOW_FORM' AND access_type = 'PRIVATE'
    AND JSON_UNQUOTE(JSON_EXTRACT(remark, '$.d')) = #{definitionId}
    AND JSON_UNQUOTE(JSON_EXTRACT(remark, '$.f')) = #{fieldPath}
    AND create_by = #{userName}


            AND biz_id = #{instanceId} AND JSON_UNQUOTE(JSON_EXTRACT(remark, '$.i')) = #{instanceId}


            AND biz_id = #{definitionId} AND NULLIF(JSON_UNQUOTE(JSON_EXTRACT(remark, '$.i')), 'null') IS NULL

choose.when:
SELECT post_id AS id, post_id AS postId, post_name AS postName, post_name AS name, post_code AS postCode
FROM sys_post WHERE tenant_id = #{tenantId} AND post_id = #{referenceId}
AND status = '0'
